def user_for(token):
    c=sqlite3.connect(DB); r=c.execute('SELECT user_id FROM tokens WHERE token=?',(token,)).fetchone(); c.close(); return r
async def handle_client(reader,writer):
    token=None; nick=None; registered=False; user=None
    async def send(x): writer.write((x+'\r\n').encode()); await writer.drain()
    try:
        while not reader.at_eof():
            raw=await reader.readline()
            if not raw: break
            line=raw.decode(errors='ignore').strip('\r\n'); parts=line.split(' ',2); cmd=parts[0].upper() if parts else ''
            arg=parts[1] if len(parts)>1 else ''; rest=parts[2] if len(parts)>2 else ''
            if cmd=='PASS':
                token=arg
                if not user_for(token): await send(':huddle 464 * :Password incorrect')
                else: user=user_for(token)
            elif cmd=='NICK':
                async with lock:
                    if arg in nicks and arg!=nick:
                        await send(f':huddle 433 * {arg} :Nickname is already in use'); continue
                    if nick:nicks.discard(nick)
