                if token and user and nick and not registered:
                    registered=True
                    for num,text in [('001','Welcome'),('002','Your host is huddle'),('003','This server was created today'),('004','huddle huddle 1'),('005','CHANTYPES=# :are supported by this server'),('422','MOTD File is missing')]:
                        await send(f':huddle {num} {nick} :{text}')
            elif cmd=='PING': await send(f':huddle PONG huddle :{arg}')
            elif cmd=='QUIT': break
            elif cmd in ('PONG','NAMES','WHO','LIST','TOPIC','MODE'): await send(f':huddle NOTICE {nick or "*"} :OK')
            elif cmd: await send(f':huddle 421 {nick or "*"} {cmd} :Unknown command')
    finally:
        if nick:
            async with lock:nicks.discard(nick)
        writer.close()
        try: await writer.wait_closed()
        except: pass
async def main():
    server=await asyncio.start_server(handle_client,'0.0.0.0',6667)
    async with server: await server.serve_forever()
if __name__=='__main__': asyncio.run(main())
